+import assert from 'node:assert/strict';
+import { after, before, describe, it } from 'node:test';
+import { parseImportCsv } from '../src/lib/csv.ts';
+import { api, startTestServer, type TestServer } from './helpers.ts';
+
+const HEADER = 'tracking,carrier,service,name,street,zip,city,country,phone';
+const QUOTED = `${HEADER}\nRR987654326AT,OEPOST,standard,"Müller, Hans","Hauptstraße 5",1030,Wien,AT,`;
+
+describe('import CSV parser', () => {
+  it('keeps commas inside quoted fields', () => {
+    const [row] = parseImportCsv(QUOTED);
+    assert.equal(row.recipient.name, 'Müller, Hans');
+    assert.equal(row.recipient.street, 'Hauptstraße 5');
+    assert.equal(row.recipient.zip, '1030');
+    assert.equal(row.recipient.city, 'Wien');
+  });
+
+  it('handles escaped quotes, CRLF and embedded newlines', () => {
+    const rows = parseImportCsv(`${HEADER}\r\nX1,DHL,,"A ""B"" C","Str\n1",1010,Wien,,\r\nX2,DHL,,Bob,S,1,W,,\r\n`);
+    assert.equal(rows.length, 2);
+    assert.equal(rows[0].recipient.name, 'A "B" C');
+    assert.equal(rows[0].recipient.street, 'Str\n1');
+    assert.equal(rows[1].recipient.name, 'Bob');
+  });
+});
+
+describe('POST /import with quoted commas', () => {
+  let srv: TestServer;
+  before(async () => {
+    srv = await startTestServer();
+  });
+  after(async () => {
+    await srv.close();
+  });
+
+  it('imports a recipient name containing a comma', async () => {
+    const res = await api(srv.url, 'POST', '/import', QUOTED);
+    assert.deepEqual(res.body.errors, []);
+    assert.equal(res.body.created, 1);
+  });
+});
